  /// view and reopens; `r<index>` resolves through the most recent
  /// picker's row list.
  Future<void> _tuiPickSession(String key) async {
    if (key == 'flat' || key == 'tree') {
      _sessionPickerFlat = key == 'flat';
      return _openSessionsPicker();
