      windowed
          ? await WindowedSessionStorage.open(
              _fs,
              metadata.path,
              parseExecutor: _parseExecutor,
              ioRetry: _ioRetry,
              timingLog: timingLog,
            )
          : await JsonlSessionStorage.open(
              _fs,
              metadata.path,
              parseExecutor: _parseExecutor,
              ioRetry: _ioRetry,
              timingLog: timingLog,
              wholeFileOnly: wholeFileOnly,
            ),
      // The repo backs the session's raw custom-record scan (the
      // obligations ledger's below-the-tail fallback, #488 class).
      customRecordScan: (types) => readCustomRecordsOfType(metadata, types),
