      '${formatTokens(cumulative.output)}, tokens '
      '${formatTokens(cumulative.totalTokens)}';
  return [
    ...lines,
    'session cumulative: $totals'
        '${showCost ? ', cost \$${cumulative.cost.total.toStringAsFixed(4)}' : ''}',
