    previous: r.previousSystemPromptHash,
  );
  _inspectManifestSection(
    lines,
    r.toolManifestHash,
    blobs,
    previous: r.previousToolManifestHash,
  );
  _inspectSection(lines, 'tools', r.activeToolNames?.join(', '));
