void _inspectAssistant(
  List<String> lines,
  TrajectoryAssistantRecord r,
  TrajectoryBlobTable blobs,
) {
  lines[0] += ' · turn ${r.turn} · step ${r.step}';
  _inspectSection(
    lines,
