  TrajectoryCellKind.context => 'CONTEXT',
  TrajectoryCellKind.compacted => 'COMPACTED',
  TrajectoryCellKind.message => 'ASSISTANT',
  TrajectoryCellKind.tool => 'TOOL',
  TrajectoryCellKind.subtool => 'SUBTOOL',
};

