      sessionPickerItems(_lastSessionRows!, flat: _sessionPickerFlat),
    );
    // For the picker tests: the items the picker opened with.
    sessionPickerItemsForTest = sessionPickerItems(
      _lastSessionRows!,
      flat: _sessionPickerFlat,
