              _fs,
              metadata.path,
              parseExecutor: _parseExecutor,
              ioRetry: _ioRetry,
              timingLog: timingLog,
            )
          : await JsonlSessionStorage.open(
              _fs,
              metadata.path,
              parseExecutor: _parseExecutor,
              ioRetry: _ioRetry,
              timingLog: timingLog,
              wholeFileOnly: wholeFileOnly,
