        MenuItem(
          key: name,
          label: name,
          description: name == _currentMode.name ? '(current)' : '',
        ),
    ];
    _tuiController?.openPicker('mode', 'Select mode', items);
  }

  void _openApprovalPicker() {
    _tuiController?.openPicker(
      'approval',
      'Approval mode',
      approvalPickerItems(),
    );
  }

