    await seedTree();
    final cli = cliFor(FakeStreamFunction([textTurn('ok')]).call);

    await cli.openSessionsPickerForTest();
    // r0: the parent row — opens it and switches to it.
    await cli.tuiPickSessionForTest('r0');
