Future<String> appendHiddenRange({required List<String> recordIds}) {
  return _append(
    (id, parentId) => HiddenRangeRecord(
      id: id,
      parentId: parentId,
      timestamp: DateTime.now(),
      recordIds: recordIds,
    ),
  );
}

