      fs,
      maybeRanged,
      filePath,
      parseExecutor,
      ioRetry,
      timingLog,
      stat.size,
      maxFullOpenBytes,
      listed,
    );
  }
  return _openWholeFileLocked(
    fs,
    filePath,
    parseExecutor,
    ioRetry,
    timingLog,
    listed,
