      }
      final kept = await session.appendMessage(UserMessage.text('kept'));
      await session.appendCompaction(
        summary: 'older turns compacted',
        firstKeptEntryId: kept,
        tokensBefore: 100000,
      );
      for (var i = 0; i < 10; i++) {
