  SessionRepo repo,
  String? sessionId,
) async {
  final sessions = await repo.list();
  if (sessions.isEmpty) return null;
  final wanted = sessionId?.trim();
  if (wanted == null || wanted.isEmpty) {
    return repo.open(sessions.first, windowed: true);
  }
  for (final metadata in sessions) {
