/// truncates each strip — a whole-ledger walk under that cap re-reads
/// and re-parses ~13x (measured on a 30k-record ledger). A no-op when
/// the window already reaches the file head.
Future<void> loadAllOlder({int maxBytes = maxWalkBlockBytes}) async {
  final top = _windowTopOffset;
  if (!_hasOlder || top == null) return;
  final records = <SessionRecord>[];
  final starts = <int>[];
  final ends = <int>[];
