void _indexChunk(SessionChunk chunk, {bool prepend = false}) {
  if (chunk.isEmpty) return;

  // The byte END of entry i ... (endOf)

  if (prepend) {
    // Block-prepend in ONE insertAll per list. Per-record insert(0) is
    // O(window) each; during a growOlderUntil walk eviction is suspended
    // so the window is unbounded and the whole walk degrades to O(n²)
    // (measured: 30k records ≈ 11× the full open, gh-1555 W1). One
    // memmove per page keeps the walk linear. Side effects stay
    // per-record, newest-first — the order the old loop ran them.
    final n = chunk.entries.length;
    final records = List<SessionRecord>.filled(n, chunk.entries.first.record);
    final starts = List<int>.filled(n, 0);
    final ends = List<int>.filled(n, 0);
    for (var i = 0; i < n; i++) {
      final entry = chunk.entries[i];
      final end = endOf(i);
      final slot = n - 1 - i; // newest-first slot order == old loop order
      records[slot] = entry.record;
      starts[slot] = entry.offset;
      ends[slot] = end;
    }
    _entries.insertAll(0, records);
    _offsets.insertAll(0, starts);
    _ends.insertAll(0, ends);
    for (var slot = 0; slot < n; slot++) {
      final record = records[slot];
      _byId[record.id] = record;
      _appendedBelow.remove(record.id);
      updateSessionLabelCache(_labelsById, record);
    }
    return;
