/// [growOlderUntil] can't do this cheaply: its doubling strips answer
/// "where is the nearby boundary", and its per-strip record cap
/// truncates each strip — a whole-ledger walk under that cap re-reads
/// and re-parses ~13x (measured on a 30k-record ledger). A no-op when
/// the window already reaches the file head.
Future<void> loadAllOlder({int maxBytes = maxWalkBlockBytes}) async {
  final top = _windowTopOffset;
  if (!_hasOlder || top == null) return;
  final records = <SessionRecord>[];
  final starts = <int>[];
  final ends = <int>[];
  var offset = 0;
  while (offset < top) {
    final budget = top - offset;
    final chunk = await _reader.readForward(
      offset,
      maxBytes: budget < maxBytes ? budget : maxBytes,
    );
    if (chunk.isEmpty) break;
    final entries = chunk.entries;
    for (var i = 0; i < entries.length; i++) {
      final entry = entries[i];
      // The offset-0 line is the session header, not a record
      // (readBlockBefore's contract), and a record already resident
      // (a concurrent append can straddle the window top) is skipped:
      // the window lists stay file-ordered and duplicate-free.
      if (entry.offset == 0 || entry.offset >= top) continue;
      if (_byId.containsKey(entry.record.id)) continue;
      records.add(entry.record);
      starts.add(entry.offset);
      ends.add(i + 1 < entries.length ? entries[i + 1].offset : entry.offset + entry.bytes + 1);
    }
    final next = chunk.limitOffset;
    if (next <= offset) break;
    offset = next;
  }
  _entries.insertAll(0, records);
  _offsets.insertAll(0, starts);
  _ends.insertAll(0, ends);
  for (var i = 0; i < records.length; i++) {
    _byId[records[i].id] = records[i];
    _offsetById[records[i].id] = starts[i];
    _appendedBelow.remove(records[i].id);
    updateSessionLabelCache(_labelsById, records[i]);
  }
  _windowTopOffset = starts.isEmpty ? _windowTopOffset : starts.first;
  _hasOlder = false;
  _aboveCount = 0;
