  if (blob == null) {
    _inspectSection(lines, 'tool manifest', manifestHash);
    return;
  }
  final previousBlob = previous == null ? null : blobs.toolManifests[previous];
  lines.add('tool manifest: $manifestHash · ${blob.tools.length} tools');
