    final TrajectoryToolRecord r => (
      text: r.result.isEmpty
          ? '${r.name} ${r.argsRaw}'.trim()
          : '${r.name} ${r.argsRaw} → ${r.result}',
      durationMillis: r.timeSeconds?.inMilliseconds,
      tokens: null,
