  for (final tool in tools) {
    lines.add('  ${tool.name}: ${tool.description}');
    if (tool.schemaJson.length <= 200) {
      lines.add('    ${tool.schemaJson}');
    } else {
      lines.add('    [schema ${tool.schemaJson.length} chars]');
    }
  }
}

