  final records = await session.getBranch();
  parseSw.stop();
  final buildSw = Stopwatch()..start();
  final baseSnapshot = trajectorySnapshotOf(records);
  buildSw.stop();
  final renderSw = Stopwatch()..start();
  var exitCode = 0;
  switch (command.verb) {
    case 'view':
      final snapshot = command.at == null
          ? baseSnapshot
